import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    import numpy as np
    from scipy import stats

    numeric_cols = ['left', 'tenure_months', 'salary', 'performance_score']
    corr_matrix = df[numeric_cols].corr(method='pearson')

    pairs = {}
    for i, c1 in enumerate(numeric_cols):
        for c2 in numeric_cols[i+1:]:
            r = corr_matrix.loc[c1, c2]
            if abs(r) >= 0.2:
                pairs[f"{c1}__{c2}"] = round(float(r), 4)

    result['correlations'] = pairs
except Exception as e:
    result['correlations'] = {"error": str(e)}

try:
    left_group = df[df['left'] == 1]['salary'].dropna()
    stayed_group = df[df['left'] == 0]['salary'].dropna()

    t_stat, p_val = stats.ttest_ind(left_group, stayed_group, equal_var=False)
    t_stat = float(t_stat)
    p_val = float(p_val)

    mean_left = float(left_group.mean())
    mean_stayed = float(stayed_group.mean())

    interp = (f"Welch t-test: t={t_stat:.3f}, p={p_val:.3g}. "
              f"Mean salary for employees who left={mean_left:.2f}, stayed={mean_stayed:.2f}. "
              + ("Significant difference in salary between groups." if p_val < 0.05
                 else "No significant difference in salary between groups."))

    result['statistical_tests'].append({
        "test_name": "Welch t-test: salary by left status",
        "statistic": round(t_stat, 4),
        "p_value": round(p_val, 6),
        "interpretation": interp
    })
except Exception as e:
    result['statistical_tests'].append({
        "test_name": "Welch t-test: salary by left status",
        "statistic": float('nan'),
        "p_value": None,
        "interpretation": f"Test failed: {str(e)}"
    })

try:
    salary_median = df['salary'].median()
    df['_salary_bin'] = (df['salary'] >= salary_median).astype(int)

    ct = df.groupby(['_salary_bin', 'left']).size().unstack(fill_value=0)
    chi2, p_chi, dof, expected = stats.chi2_contingency(ct)
    chi2 = float(chi2)
    p_chi = float(p_chi)

    interp_chi = (f"Chi-square test of independence (salary above/below median vs left): "
                  f"chi2={chi2:.3f}, p={p_chi:.3g}, dof={dof}. "
                  + ("Significant association between salary level and attrition." if p_chi < 0.05
                     else "No significant association between salary level and attrition."))

    result['statistical_tests'].append({
        "test_name": "Chi-square: salary (median split) vs left",
        "statistic": round(chi2, 4),
        "p_value": round(p_chi, 6),
        "interpretation": interp_chi
    })

    df.drop(columns=['_salary_bin'], inplace=True)
except Exception as e:
    result['statistical_tests'].append({
        "test_name": "Chi-square: salary (median split) vs left",
        "statistic": float('nan'),
        "p_value": None,
        "interpretation": f"Test failed: {str(e)}"
    })

try:
    r_salary_left, p_point = stats.pearsonr(df['salary'].dropna(), df['left'].dropna())
    r_salary_left = float(r_salary_left)
    p_point = float(p_point)

    interp_pt = (f"Pearson r between salary and left: r={r_salary_left:.3f}, p={p_point:.3g}. "
                 + ("Significant linear association." if p_point < 0.05
                    else "No significant linear association."))

    result['statistical_tests'].append({
        "test_name": "Pearson correlation: salary vs left",
        "statistic": round(r_salary_left, 4),
        "p_value": round(p_point, 6),
        "interpretation": interp_pt
    })
except Exception as e:
    result['statistical_tests'].append({
        "test_name": "Pearson correlation: salary vs left",
        "statistic": float('nan'),
        "p_value": None,
        "interpretation": f"Test failed: {str(e)}"
    })

result['assumptions'] = [
    "Welch t-test used (unequal variances assumed between left=0 and left=1 groups).",
    "Chi-square salary split uses dataset median as threshold.",
    "left column treated as binary (0=stayed, 1=left); Pearson r on binary outcome is point-biserial.",
    "Correlations reported only for |r| >= 0.2; weaker pairs omitted.",
    "Full dataset used (no date filtering); imputed or missing rows excluded per column."
]

# ─── Standard statistics (deterministic) ───
result['builtin'] = []
_targets, _segs, _date, _hints = ['salary', 'left'], [], 'hire_date', {'left': ['mean', [], None], 'salary': ['mean', [], None]}
try:
    if True:
        for _i, _a in enumerate(_targets):
            for _b in _targets[_i + 1:]:
                if f'{_a}__{_b}' not in result['correlations'] and f'{_b}__{_a}' not in result['correlations']:
                    _r = df[_a].corr(df[_b])
                    if _r == _r:
                        result['correlations'][f'{_a}__{_b}'] = round(float(_r), 4)
                        result['builtin'].append(f'corr:{_a}__{_b}')
except Exception:
    pass
try:
    if (_date or _hints) and False:
        # A mid-month export compares the last two complete months (agents.utils.partial_last_month).
        def _cut(_t):
            _mm = _t.dt.to_period('M')
            _d = _t.dropna()
            if _d.empty:
                return _mm
            _days = _d.dt.normalize().groupby(_d.dt.to_period('M')).nunique().sort_index()
            if len(_days) >= 3 and _d.max().normalize() < _d.max().normalize() + pd.offsets.MonthEnd(0) and _days.iloc[-1] < 0.9 * _days.iloc[:-1].median():
                _mm = _mm.where(_mm != _days.index[-1])
            return _mm
        _month = _cut(pd.to_datetime(df[_date], errors='coerce')) if _date else pd.Series(pd.NaT, index=df.index).dt.to_period('M')
        def _level_months(_tc):
            return _cut(pd.to_datetime(df[_tc], format='mixed', errors='coerce'))
        # One definition of MoM (calendar-month totals), so the built-in value replaces the model's.
        result['trends'] = [t for t in result['trends'] if not (isinstance(t, dict) and t.get('period') == 'MoM' and t.get('column') in _targets)]
        # ponytail: values all in [0, 1] → a rate or flag, compared by month mean; anything else
        # by month total. A semantic layer (Phase 4) can declare the aggregation instead.
        # The semantic layer, when it matched (Phase 5.5): a level (balance, MRR) is each entity's
        # last value in the month, summed; a reading is a mean.
        def _mom(_frame, _col):
            _h = _hints.get(_col)
            _agg = _h[0] if _h else ('mean' if df[_col].dropna().between(0, 1).all() else 'sum')
            _mon = _month
            if _agg in ('last', 'first'):
                if not _h[1] or not all(_e in df.columns for _e in _h[1]) or _h[2] not in df.columns:
                    return None, 0   # its account (or time) column is gone: no total, never a sum
                _mon = _level_months(_h[2])   # the level's own months, partial last month out
                _f = _frame.assign(_t=pd.to_datetime(_frame[_h[2]], format='mixed', errors='coerce'),
                                   _m=_mon.loc[_frame.index])
                _f = _f.dropna(subset=['_m', '_t', _col]).sort_values('_t', kind='stable')
                _tot = _f.groupby(['_m', *_h[1]])[_col].agg(_agg).groupby(level=0).sum().sort_index()
            else:
                _tot = _frame.groupby(_month.loc[_frame.index])[_col].agg(_agg).sort_index()
            if len(_tot) < 2 or _tot.iloc[-2] == 0:
                return None, 0
            _last2 = _mon.loc[_frame.index].isin(_tot.index[-2:])
            _n = int(_frame.loc[_last2, _col].notna().sum())
            return round(float((_tot.iloc[-1] / _tot.iloc[-2] - 1) * 100), 2), _n
        for _c in _targets:
            _jobs = [(None, df)]
            if _segs:
                _top = df[_segs[0]].value_counts().head(10).index
                _jobs += [(str(_v), df[df[_segs[0]] == _v]) for _v in _top]
            for _seg, _frame in _jobs:
                _p, _n = _mom(_frame, _c)
                if _p is not None:
                    result['trends'].append({'column': _c, 'period': 'MoM', 'pct_change': _p, 'segment': _seg, 'n': _n,
                                             'direction': 'up' if _p > 0 else 'down' if _p < 0 else 'flat'})
                    result['builtin'].append(f'trend:{_c}' + (f' ({_seg})' if _seg else '') + ':MoM')
except Exception:
    pass
try:
    if len(_segs) >= 2 and 'segmentation' in ['correlation', 'hypothesis']:
        _joint = '|'.join(_segs[:2])
        for _c in _targets:
            if any(s.get('segment_column') == _joint and s.get('metric_column') == _c for s in result['segments'] if isinstance(s, dict)):
                continue
            _g = df.groupby(_segs[:2])[_c].mean()
            _n = df.groupby(_segs[:2]).size().sort_values(ascending=False).head(20).index
            result['segments'].append({'segment_column': _joint, 'metric_column': _c, 'aggregation': 'mean',
                                       'results': [{'name': f'{_a}|{_b}', 'value': round(float(_g[(_a, _b)]), 4)} for _a, _b in _n]})
            result['builtin'].append(f'seg:{_joint}/{_c}')
