import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    seg_col = "region"
    metric_col = "claim_amount"

    region_groups = df.groupby(seg_col)[metric_col].agg(["sum", "mean", "count"]).reset_index()
    region_groups.columns = [seg_col, "sum", "mean", "count"]
    top10 = region_groups.nlargest(10, "count")

    result["segments"].append({
        "segment_column": seg_col,
        "metric_column": metric_col,
        "aggregation": "sum",
        "label": "total_claim_amount_by_region",
        "results": [{"name": str(r[seg_col]), "value": float(r["sum"])} for _, r in top10.iterrows()]
    })

    result["segments"].append({
        "segment_column": seg_col,
        "metric_column": metric_col,
        "aggregation": "mean",
        "label": "mean_claim_amount_by_region",
        "results": [{"name": str(r[seg_col]), "value": float(r["mean"])} for _, r in top10.iterrows()]
    })

    result["segments"].append({
        "segment_column": seg_col,
        "metric_column": metric_col,
        "aggregation": "count",
        "label": "policy_count_by_region",
        "results": [{"name": str(r[seg_col]), "value": float(r["count"])} for _, r in top10.iterrows()]
    })

    total_claim = df[metric_col].sum()
    region_sum = df.groupby(seg_col)[metric_col].sum()
    ratio_results = [{"name": str(k), "value": float(v / total_claim) if total_claim > 0 else 0.0}
                     for k, v in region_sum.items()]
    result["segments"].append({
        "segment_column": seg_col,
        "metric_column": metric_col,
        "aggregation": "ratio",
        "label": "claim_amount_share",
        "results": ratio_results
    })

    line_col = "line"
    line_region_groups = df.groupby([line_col, seg_col])[metric_col].sum().reset_index()
    line_region_groups["group"] = line_region_groups[line_col].astype(str) + "|" + line_region_groups[seg_col].astype(str)
    top10_lr = line_region_groups.nlargest(10, metric_col)
    result["segments"].append({
        "segment_column": f"{line_col}|{seg_col}",
        "metric_column": metric_col,
        "aggregation": "sum",
        "label": "total_claim_amount_by_line_region",
        "results": [{"name": str(r["group"]), "value": float(r[metric_col])} for _, r in top10_lr.iterrows()]
    })

    line_region_mean = df.groupby([line_col, seg_col])[metric_col].mean().reset_index()
    line_region_mean["group"] = line_region_mean[line_col].astype(str) + "|" + line_region_mean[seg_col].astype(str)
    top10_lrm = line_region_mean.nlargest(10, metric_col)
    result["segments"].append({
        "segment_column": f"{line_col}|{seg_col}",
        "metric_column": metric_col,
        "aggregation": "mean",
        "label": "mean_claim_amount_by_line_region",
        "results": [{"name": str(r["group"]), "value": float(r[metric_col])} for _, r in top10_lrm.iterrows()]
    })

except Exception as e:
