}

try:
    numeric_cols = ['on_time', 'distance_km', 'weight_kg', 'delivery_days', 'cost']
    corr_matrix = df[numeric_cols].corr(method='pearson')
    pairs = {}
    for i, c1 in enumerate(numeric_cols):
        for c2 in numeric_cols[i+1:]:
            r = corr_matrix.loc[c1, c2]
            if abs(r) >= 0.2:
                pairs[f"{c1}__{c2}"] = round(float(r), 4)
    result['correlations'] = pairs
except Exception:
    pass

try:
    from scipy import stats
    x = df['distance_km'].dropna()
    y = df['delivery_days'].dropna()
    common = df[['distance_km', 'delivery_days']].dropna()
    x_c = common['distance_km']
    y_c = common['delivery_days']
    r, p = stats.pearsonr(x_c, y_c)
    r = round(float(r), 4)
    p = float(p)
    result['statistical_tests'].append({
        "test_name": "Pearson correlation: distance_km vs delivery_days",
        "statistic": r,
        "p_value": round(p, 6),
        "interpretation": f"r={r:.4f}, p={p:.3g}; {'significant positive linear association between distance and delivery days' if p < 0.05 else 'no significant relationship'}"
    })
except Exception:
    pass

try:
